<?php
require __DIR__.'/config.php';require_role(['admin']);$pageTitle='User accounts';$activePage='users';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['full_name']??'');$username=trim($_POST['username']??'');$password=$_POST['password']??'';$role=$_POST['role']??'officer';
 if($name===''||$username===''||strlen($password)<10||!in_array($role,['admin','officer','viewer'],true))$errors[]='Complete all fields and use a password of at least 10 characters.';
 else {try{$st=$pdo->prepare('INSERT INTO users(full_name,username,password_hash,role) VALUES(?,?,?,?)');$st->execute([$name,$username,password_hash($password,PASSWORD_DEFAULT),$role]);flash('success','User account created.');redirect('/users.php');}catch(PDOException $e){$errors[]='Could not create user. The username may already exist.';}}
}
$users=$pdo->query('SELECT id,full_name,username,role,active,created_at FROM users ORDER BY created_at DESC')->fetchAll();require __DIR__.'/includes/header.php';
?>
<div class="page-intro"><p class="eyebrow">ACCESS CONTROL</p><h1>User accounts</h1><p class="muted">Create named accounts and assign least-privilege roles.</p></div>
<?php if($errors):?><div class="alert error"><?php foreach($errors as $x):?><?=e($x)?><br><?php endforeach;?></div><?php endif;?>
<div class="detail-grid"><article class="panel"><div class="panel-heading"><div><h2>Create account</h2><p>Passwords are stored as secure hashes.</p></div></div><form method="post" class="stack-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Full name<input name="full_name" required></label><label>Username<input name="username" required></label><label>Password (10+ characters)<input type="password" name="password" minlength="10" required></label><label>Role<select name="role"><option value="officer">Officer</option><option value="viewer">Viewer (read-only)</option><option value="admin">Administrator</option></select></label><button class="btn primary">Create account</button></form></article><article class="panel"><div class="panel-heading"><div><h2>Registered users</h2><p><?=count($users)?> account(s)</p></div></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Username</th><th>Role</th><th>Status</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['full_name'])?></td><td><?=e($u['username'])?></td><td><?=e(ucfirst($u['role']))?></td><td><span class="status"><?=((int)$u['active']===1)?'Active':'Inactive'?></span></td></tr><?php endforeach;?></tbody></table></div></article></div>
